212	  --animate-progress-fill: progress-fill 320ms cubic-bezier(0.2, 0, 0, 1) both;
213	  --animate-progress-sweep: progress-sweep 1280ms cubic-bezier(0.2, 0, 0, 1) 320ms infinite;
214	  @keyframes progress-fill { from { transform: scaleX(0); } to { transform: scaleX(1); } }
215	  @keyframes progress-sweep { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }
